   <a class="skip-link" href="#main-content">Skip to main content</a>
   <div id="root"></div>
   <script>
     const options = [
       {
         id: "notify-email",
         value: "Email",
         label: "Email",
         description: "Receive updates in your inbox for easy reference."
       },
       {
         id: "notify-sms",
         value: "SMS",
         label: "SMS",
         description: "Get short alerts delivered directly to your phone."
       },
       {
         id: "notify-push",
         value: "Push Notifications",
         label: "Push Notifications",
         description: "See real-time prompts from the app as soon as they happen."
       }
     ];

     function RadioOption(option) {
       return `
         <label class="radio-option" for="${option.id}">
           <input id="${option.id}" type="radio" name="notificationPreference" value="${option.value}" required>
           <span class="radio-content">
             <span class="radio-label">${option.label}</span>
             <span class="radio-description">${option.description}</span>
           </span>
         </label>
       `;
     }

     function NotificationQuestion() {
       return `
         <div class="form-field">
           <fieldset aria-describedby="notification-help notification-status">
             <legend>How do you prefer to receive notifications? <span class="required-indicator" aria-hidden="true">*</span></legend>
             <p class="field-note" id="notification-help">Choose one option to set your preferred notification channel.</p>
             <div class="radio-list">
               ${options.map(RadioOption).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function PreferenceForm() {
       return `
         <form class="form-panel" id="preference-form" novalidate>
           ${NotificationQuestion()}
           <div class="form-actions">
             <button class="submit-button" type="submit">Submit</button>
             <p class="status-message" id="notification-status" aria-live="polite" data-state="idle"></p>
           </div>
         </form>
       `;
     }

     function App() {
       return `
         <div class="page-shell">
           <header class="page-header">
             <div class="brand-mark" aria-label="Pulse product">
               <span class="brand-mark__badge" aria-hidden="true"></span>
               <span>Pulse</span>
             </div>
           </header>
           <main class="page-main" id="main-content">
             <section class="app-card" aria-labelledby="page-title">
               <p class="eyebrow">Account preferences</p>
               <h1 id="page-title">Choose your notification preference</h1>
               <p class="intro">Tell us where you want updates delivered so we can keep your account activity timely and relevant.</p>
               ${PreferenceForm()}
             </section>
           </main>
         </div>
       `;
     }

     document.getElementById("root").innerHTML = App();

     const form = document.getElementById("preference-form");
     const status = document.getElementById("notification-status");
     const radios = Array.from(form.elements.notificationPreference);

     function setStatus(message, state) {
       status.textContent = message;
       status.dataset.state = state;
     }

     function updateValidityState() {
       const hasSelection = radios.some((radio) => radio.checked);
       radios.forEach((radio) => {
         radio.setAttribute("aria-invalid", hasSelection ? "false" : "true");
       });
       return hasSelection;
     }

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         updateValidityState();
         setStatus("", "idle");
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       const isValid = updateValidityState();

       if (!isValid) {
         setStatus("Please choose a notification method before submitting.", "error");
         radios[0].focus();
         return;
       }

       const selectedOption = radios.find((radio) => radio.checked);
       setStatus(`Preference saved: ${selectedOption.value}.`, "success");
     });
   </script>
